import pandas as pd
D=pd.read_csv('ev.csv');T=pd.read_csv('top10.csv');B=pd.read_csv('top_by_tf.csv');C=pd.read_csv('coef_bins.csv')
md=lambda d:d.round(3).to_markdown(index=False)
C=C[~C.bin.str.contains('zq')]
s=["# 밝기 세분화 특징 (bright_fine)\n","- 특징: 상대(이미지별 z, σ2 블러, −3~3 0.25간격 24구간 + z분위수 9개 + 주요 z구간 10개의 연결성분 수/평균/최대 크기), 절대(0~255 16·32구간 면적비, 분위수, 임계값 64~192 이하 면적비와 연결성분). 원본·CLAHE(2.5,8×8)·전역 스트레치(p1/p99=92/189)·스트레치+감마0.85 각각 계산.\n- 평가: 10회 반복 5-fold nested CV(ablation_all과 같은 seed 100+s), 블렌드는 NNLS(내부 OOF로 가중).\n","## 결과: 최고 블렌드 12.601 대비 0.05 이상 개선 없음 → 후보 CSV 만들지 않음\n최고는 LGB(원본+3변환) 추가 12.587(−0.014, sd 0.023로 노이즈 범위). 고경도 편향 −27.2 그대로.\n","## 전체 표 (A=단순기준 단독, B=최고블렌드에 추가)\n",md(D),"\n## 고경도 18장 vs 대조군(170~230) 효과크기 상위 10 (원본)\n",md(T),"\n해석: 상위는 거의 '상대' 연결성분 특징. 고경도는 각 z구간의 덩어리 **개수가 적고 최대/평균 크기가 큼**(굵고 큰 상 덩어리). 면적비 자체는 z≈0 구간이 약간 적은 정도(d −0.99).\n","## 변환별 고경도 분리 상위 5 구간\n",md(B),"\n변환별로 거의 같은 신호(z −1.5~−0.5 덩어리 수↓, 최대크기↑). CLAHE만 절대 128 이하 면적·최대 덩어리가 상위로 올라옴.\n","## 최종 Ridge 구간 면적비 표준화 계수 (base+해당 구간 세트, 전체 500장 적합)\n","그림: coef_bins.png (행=원본/clahe/stretch/gamma, 열=상대 z / 절대16 / 절대32, 빨강=경도↑ 파랑=경도↓)\n"]
for (a,b),g in C.groupby(['tf','set'],sort=False):
    s.append(f"\n**{a} / {b}**\n\n"+'| '+' | '.join(x.split('_')[-1] for x in g.bin)+' |\n|'+'---|'*len(g)+'\n| '+' | '.join(f'{v:+.2f}' for v in g.coef_std)+' |\n')
s.append("\n요약(공통 패턴): 상대 z −1.5~−1.0(어두운 2차상)과 +1.0~+1.75(밝은 쪽) 면적이 클수록 경도↑, z −0.5~+0.25(바탕 기지)와 극단 밝음 z≥+2.25 면적이 클수록 경도↓. 절대값으로는 약 32~112(어두운 쪽)↑, 128~160↓. 다만 구간 간 공선성이 커서 계수 크기는 참고용.\n")
open('report.md','w').write('\n'.join(s))
